object Solution {
  val MOD = 1000000007

  // Precompute binomial coefficients (nCr) using Pascal's triangle up to 1000
  val maxN = 1000
  val comb: Array[Array[Long]] = Array.ofDim[Long](maxN + 1, maxN + 1)
  for (i <- 0 to maxN) {
    comb(i)(0) = 1L
    comb(i)(i) = 1L
  }
  for (i <- 2 to maxN) {
    for (j <- 1 until i) {
      comb(i)(j) = (comb(i - 1)(j - 1) + comb(i - 1)(j)) % MOD
    }
  }

  def numOfWays(nums: Array[Int]): Int = {
    def dfs(arr: Array[Int]): Long = {
      if (arr.length <= 2) return 1L

      val root = arr(0)
      val left = arr.tail.filter(_ < root)
      val right = arr.tail.filter(_ > root)

      val leftWays = dfs(left)
      val rightWays = dfs(right)

      val leftSize = left.length
      val rightSize = right.length

      val ways = (comb(leftSize + rightSize)(leftSize) * leftWays) % MOD
      (ways * rightWays) % MOD
    }

    // The problem asks for the number of ways excluding the original order,
    // so subtract 1 from the result.
    val res = dfs(nums) - 1
    if (res < 0) 0 else (res % MOD).toInt
  }
}

